"""Reconstruct R2 from public observations. Default rebuild uses tracked inputs.

--from-raw also reproduces the two extracts from the pinned provider files.
--check compares every generated byte with the reviewed checkpoint.
"""
import argparse
import calendar
import csv
import hashlib
import json
import math
from collections import defaultdict
from pathlib import Path
from tempfile import TemporaryDirectory

import r2_model as model

ROOT = Path(__file__).resolve().parents[1]
OLD = Path('data/derived/episode_2026_11_09')
EXTRACTS = Path('data/derived/r2_2026_11_11')
REPORT = Path('reports/r2_2026_11_11')
SECTORS = ('government', 'central_bank', 'banks', 'other_sectors', 'di')
PERIODS = [f'{year}Q4' for year in range(2020, 2026)] + ['2026Q1', '2026Q2']


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def load_json(path):
    return json.loads(path.read_text())


def rows(path):
    with path.open(newline='') as stream:
        return list(csv.DictReader(stream))


def csv_file(path, records):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('w', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=list(records[0]), lineterminator='\n')
        writer.writeheader()
        for row in records:
            writer.writerow({k: format(v, '.9f') if isinstance(v, float) else v for k, v in row.items()})


def at_quarter_end(period):
    year, quarter = map(int, period.split('Q'))
    month = 3 * quarter
    return f'{year}-{month:02}-{calendar.monthrange(year, month)[1]}'


def last_four(period):
    year, quarter = map(int, period.split('Q'))
    index = year * 4 + quarter - 1
    return [f'{i // 4}Q{i % 4 + 1}' for i in range(index - 3, index + 1)]


def extract_public(temp, source_map):
    import openpyxl

    def pinned(ident):
        row = source_map[ident]
        path = ROOT / row['local_path']
        if digest(path) != row['sha256']:
            raise ValueError(f'Provider hash mismatch: {ident}')
        return path

    metadata, definitions = load_json(pinned('qeds_series'))
    assert metadata['pages'] == 1
    definitions = {d['id']: d['name'] for d in definitions}
    records = []
    for ident, item in sorted(source_map.items()):
        if not ident.startswith('qeds_') or ident == 'qeds_series':
            continue
        meta, data = load_json(pinned(ident))
        assert meta['sourceid'] == '22' and meta['pages'] == 1 and len(data) == meta['total']
        assert len({d['date'] for d in data}) == len(data)
        for row in sorted(data, key=lambda d: d['date']):
            assert row['country']['id'] == 'GEO' and row['indicator']['id'] == item['series']
            assert row['indicator']['value'] == definitions[item['series']]
            records.append(dict(source=ident, series=item['series'], quarter=row['date'],
                                value_usd=row['value'], label=definitions[item['series']],
                                value_status='missing' if row['value'] is None else 'reported',
                                provider_update=meta['lastupdated']))
    csv_file(temp / EXTRACTS / 'qeds.csv', records)

    workbook = openpyxl.load_workbook(pinned('iip'), read_only=True, data_only=True)
    sheet = workbook['IIP-1 (BPM6)']
    matrix = list(sheet.values)
    from openpyxl.utils import get_column_letter
    bank = []
    for j, date in enumerate(matrix[2]):
        if not hasattr(date, 'date') or date.date().isoformat() not in map(at_quarter_end, PERIODS):
            continue
        for i, field in [(48, 'bank_st_debt_security_assets'), (80, 'bank_st_deposit_assets'),
                         (261, 'bank_st_deposit_liabilities')]:
            assert 'Deposit-taking corporations' in matrix[i-2][0] and matrix[i-1][0].strip() == 'Short-term'
            assert isinstance(matrix[i-1][j], (float, int))
            bank.append(dict(date=date.date().isoformat(), field=field, value_usdm=matrix[i-1][j],
                             source='iip', sheet=sheet.title, cell=f'{get_column_letter(j+1)}{i}'))
    workbook.close()
    assert len(bank) == 3 * len(PERIODS)
    csv_file(temp / EXTRACTS / 'bank_exposures.csv', bank)


class Research:
    def __init__(self, temp, raw):
        self.temp = temp
        self.extract_root = temp if raw else ROOT
        self.inputs = {}
        self.checks = []

    def read(self, path):
        location = (self.extract_root if path.parent == EXTRACTS else ROOT) / path
        self.inputs[str(path)] = digest(location)
        return rows(location)

    def save(self, name, data):
        csv_file(self.temp / REPORT / (name + '.csv'), data)

    def check_close(self, label, a, b, tolerance):
        difference = abs(a - b)
        if difference > tolerance or not math.isfinite(difference):
            raise ValueError(f'{label}: {difference} exceeds {tolerance}')
        self.checks.append(dict(check=label, difference=difference, tolerance=tolerance))

    def adequacy(self):
        qeds = {(r['source'], r['quarter']): float(r['value_usd']) / 1e6 if r['value_usd'] else None
                for r in self.read(EXTRACTS / 'qeds.csv')}
        self.qeds = qeds
        bank = {(r['date'], r['field']): float(r['value_usdm']) for r in self.read(EXTRACTS / 'bank_exposures.csv')}
        stocks = {r['date']: float(r['reserves_usdm']) for r in self.read(OLD / 'reserve_stocks_monthly.csv')}
        exchange = {r['date']: float(r['usd_gel']) for r in self.read(OLD / 'official_fx_daily.csv')}
        money = {r['date']: r for r in self.read(OLD / 'money_aggregates_monthly.csv')}
        dcs = {r['date']: float(r['value_gelm']) for r in self.read(Path('reports/r1_2026_11_10/depository_survey.csv'))
               if r['series_row'] == '17'}
        iip = {(r['date'], r['series_row']): float(r['value']) for r in self.read(OLD / 'iip.csv') if r['value']}
        exports = {r['date']: float(r['value']) for r in self.read(OLD / 'bop_bpm6.csv') if r['series_row'] == '8' and r['value']}
        imf = {(r['year'], r['indicator']): float(r['value']) for r in self.read(OLD / 'imf_ara_published.csv')}
        legacy = {r['year']: r for r in self.read(Path('archive/legacy/reports/reserve_foundations/ara_reconstruction.csv'))}
        native = {r['year']: r for r in self.read(Path('reports/acquisition_2026_11_09/ara_component_inputs.csv'))}
        components, adjusted, concordance, debt = [], [], [], []
        for period in PERIODS:
            date = at_quarter_end(period)
            year = date[:4]
            annual = period.endswith('Q4')
            p = {k: qeds['qeds_principal_' + k, period] for k in ('total',) + SECTORS}
            self.check_close('QEDS sector sum ' + period, p['total'], sum(p[k] for k in SECTORS), 0.000001)
            st = p['total'] - p['di']
            debt.append(dict(quarter=period, **{k+'_usdm': v for k,v in p.items()},
                             non_di_principal_usdm=st, supplementary_position_usdm=qeds['qeds_remaining_total', period],
                             source='QEDS SDDS Table 4, principal only', supplementary_status='excluded: zero conflicts with positive principal or source missing'))
            export = sum(exports[q] for q in last_four(period))
            if annual:
                self.check_close('Quarterly vs annual exports '+period, export, exports[year], .001)
            portfolio, other = iip[date,'211'], iip[date,'254']
            other_liabilities = portfolio + other - st
            assert other_liabilities >= 0
            for aggregate in ('m2', 'm3'):
                if date == '2026-06-30':
                    # Monetary Ratios row 372 carries June 1. DCS independently
                    # dates the identical broad-money stock to June 30.
                    if aggregate == 'm2':
                        continue
                    nominal = dcs[date]
                    self.check_close('June broad-money cross-source level', nominal,
                                     float(money['2026-06-01']['m3_gelm']), .001)
                    locator = 'DCS DY17, June 30'
                else:
                    nominal = float(money[date][aggregate + '_gelm'])
                    locator = 'Monetary Ratios row ' + money[date]['source_row']
                m = nominal / exchange[date]
                contributions = [0.05*export, 0.05*m, 0.30*st, 0.15*other_liabilities]
                denominator = sum(contributions)
                coverage = 100 * stocks[date] / denominator
                self.check_close('Overlap identity '+period+' '+aggregate, denominator,
                                 0.05*(export+m) + 0.15*(portfolio+other+st), .000001)
                if annual:
                    self.check_close('Prior national money '+period+' '+aggregate, m,
                                     float(native[year][aggregate+'_usdm']), .000001)
                components.append(dict(quarter=period, period_basis='calendar year' if annual else 'trailing four quarters',
                    money_series=aggregate.upper(), money_locator=locator, gir_usdm=stocks[date], exports_usdm=export,
                    gel_per_usd=exchange[date], broad_money_usdm=m, portfolio_liabilities_usdm=portfolio,
                    other_investment_liabilities_usdm=other, one_year_non_di_principal_usdm=st,
                    other_liabilities_after_subtraction_usdm=other_liabilities,
                    exports_contribution_usdm=contributions[0], money_contribution_usdm=contributions[1],
                    debt_contribution_usdm=contributions[2], other_liabilities_contribution_usdm=contributions[3],
                    ara_usdm=denominator, reserves_to_ara_pct=coverage,
                    classification='independent public-input construction, QEDS cash schedule convention'))
                assets = bank[date,'bank_st_deposit_assets'] + bank[date,'bank_st_debt_security_assets']
                liabilities = bank[date,'bank_st_deposit_liabilities']
                for share in (0, .5, 1):
                    covered = min(assets * share, liabilities, st)
                    after = denominator - .30 * covered
                    adjusted.append(dict(quarter=period, money_series=aggregate.upper(), accessible_fraction_assumed=share,
                        short_deposit_assets_usdm=bank[date,'bank_st_deposit_assets'],
                        short_security_assets_usdm=bank[date,'bank_st_debt_security_assets'],
                        short_deposit_liabilities_usdm=liabilities, covered_usdm=covered, adjusted_denominator_usdm=after,
                        conditional_coverage_pct=100*stocks[date]/after,
                        status='bank self-insurance sensitivity, official adjustment unresolved'))
                if not annual:
                    continue
                benchmarks = [('IMF DataMapper April 2026', imf[year,'Reserves_ARA']*100, 'published ratio')]
                if year in ('2022','2023'):
                    benchmarks.append(('IMF 2024 Article IV p53', float(legacy[year]['reported_coverage_pct']), 'historical staff estimate'))
                if year == '2024':
                    benchmarks.append(('IMF 2025 Article IV p58',77.3,'historical staff estimate, external assessment'))
                if year == '2025':
                    benchmarks.append(('IMF 2026 Article IV p4',100.0,'historical staff estimate'))
                if native[year]['nbg_reported_ara_pct']:
                    benchmarks.append(('NBG Annual Report 2025 p47',float(native[year]['nbg_reported_ara_pct']), 'national published ratio'))
                for name, pct, status in benchmarks:
                    implied = stocks[date] * 100 / pct
                    concordance.append(dict(year=year, benchmark=name, benchmark_status=status,
                        money_series=aggregate.upper(), published_pct=pct, reconstructed_pct=coverage, gap_pp=coverage-pct,
                        denominator_rebuilt_usdm=denominator, implied_denominator_at_common_gir_usdm=implied,
                        residual_usdm=denominator-implied, shared_numerator_assumption='diagnostic only'))
        self.save('ara_components', components)
        self.save('one_year_principal', debt)
        self.save('bank_buffer_sensitivity', adjusted)
        self.save('ara_vintage_concordance', concordance)
        self.end2025 = next(r for r in components if r['quarter']=='2025Q4' and r['money_series']=='M3')
        # Earlier vintages keep their own reported GIR, denominator and adjustment.
        self.save('historical_adjustment_check', [dict(year=y, published_adjusted_usdm=legacy[y]['published_adjusted_ara_usd_m'],
            simple_adjusted_usdm=legacy[y]['simple_net_bank_adjusted_ara_usd_m'], gap_usdm=legacy[y]['adjustment_residual_usd_m'],
            source='IMF 2024 Article IV p53, preserved historical calculation') for y in ('2022','2023')])

    def debt_crosscheck(self):
        data = {r['source_cell']: float(r['value_usdm']) for r in self.read(OLD / 'external_debt_payment_schedule.csv')
                if r['sheet']=='ED-Service' and r['value_usdm']}
        result = []
        for sector, row in zip(('government','central_bank','banks','other_sectors','di','total'),(7,12,15,23,35,40)):
            national = sum(data[col + str(row)] for col in 'BCDEF')
            wb = self.qeds['qeds_principal_'+sector,'2026Q2']
            result.append(dict(quarter='2026Q2', sector=sector, nbg_cell_range=f'ED-Service B{row}:F{row}',
                               nbg_usdm=national, qeds_usdm=wb, qeds_minus_nbg_usdm=wb-national,
                               status='within USD 1' if abs(wb-national)<.000001 else 'unresolved source difference'))
        self.check_close('Sector differences explain total mismatch',sum(r['qeds_minus_nbg_usdm'] for r in result[:-1]),
                         result[-1]['qeds_minus_nbg_usdm'], .000001)
        self.save('national_qeds_reconciliation', result)

    def liquidity(self):
        form = defaultdict(dict)
        for r in self.read(OLD / 'reserve_liquidity_cells.csv'):
            if '2024-12-31' <= r['date'] <= '2026-09-30':
                form[r['date']][r['source_cell']] = float(r['value']) if r['value'] else None
        schedule, stress = [], []
        for date, c in sorted(form.items()):
            self.check_close('Section II maturity columns '+date, c['D54'], sum(c[k+'54'] for k in 'EFG'), .001)
            self.check_close('Section III maturity columns '+date, c['C77'], sum(c[k+'77'] for k in 'DEF'), .001)
            self.check_close('Reserve composition '+date, c['D21'], sum(c[k] for k in ('D22','D31','D32','D33','D35')), .001)
            for months, cols, contingents in [(1,'E','D'),(3,'EF','DE'),(12,'EFG','DEF')]:
                drains = sum(c[k+'54'] for k in cols)
                contingent = sum(c[k+'77'] for k in contingents)
                schedule.append(dict(date=date, horizon_months=months, headline_usdm=c['D21'],
                    deposits_usdm=c['D25'], fx_securities_usdm=c['D23'], sdr_usdm=c['D32'], imf_position_usdm=c['D31'],
                    gold_usdm=c['D33'], other_reserve_assets_usdm=c['D35'], sdr_basket_currencies_usdm=c['D160'],
                    other_currencies_usdm=c['D161'], reported_II_1_signed_usdm=drains,
                    reported_III_1_signed_usdm=contingent, pledge_memo_in_reserves_usdm=c['D134'],
                    repo_lent_in_reserves_usdm=c['D137'], after_reported_II_1_usdm=c['D21']+drains,
                    unconditional_usable_reserves_usdm=None, source='NBG template I, II.1, III.1 and IV'))
                for gold_discount, call_share in [(0,0),(0,1),(1,0),(1,1)]:
                    stress.append(dict(date=date, horizon_months=months, gold_unavailable_share=gold_discount,
                        contingent_called_share=call_share, conditional_remaining_usdm=c['D21']+drains+call_share*contingent-gold_discount*c['D33'],
                        assumptions='no other net flows or asset discounts, face-value realization of available assets, disjoint incremental claims'))
        self.save('liquidity_schedule', schedule)
        self.save('liquidity_stress', stress)

    def model_audit(self):
        r = self.end2025['gir_usdm'] / 38100  # 2026 Article IV p4, GDP in USD millions.
        prob, slope = .10, .0575  # Annex p14 interpreted in fraction units
        root, intercept = model.minimum_intercept(prob, .10, slope)
        diagnostics = [
            ('spread_decrease_from_10_to_20_pct_gdp', 10000*slope*math.log(1.2/1.1),'basis points','p14 footnote unit check'),
            ('actual_end_2025_gir_to_gdp', 100*r, 'percent','GIR statistical vintage / rounded GDP from 2026 Article IV p4'),
            ('implied_private_dollarization',100*(.6-.1*math.log1p(r)),'percent','p15 channel at observed reserve ratio, model output'),
            ('implied_crisis_loss',100*model.crisis_loss(r),'percent of GDP','p15 conditional loss function'),
            ('isolated_marginal_loss_benefit',10000*(-prob/(1-prob)*model.loss_derivative(r)), 'basis points of marginal carrying rate','conditional on p15 loss channel and common horizon'),
            ('p14_stationary_point_of_required_intercept',root,'R/GDP','p14, illustrative fixed loss=0.10, probability=0.10, k=0.0575'),
            ('p14_two_root_threshold',10000*intercept,'basis points','p14 same illustration, sum rho+s0 above threshold gives two positive roots'),
        ]
        self.save('model_equation_checks',[dict(quantity=a,value=b,unit=c,scope=d) for a,b,c,d in diagnostics])
        self.save('model_target_status',[dict(channel=a,reported=b,unit=c,independently_replicated_value=None,missing=d)
            for a,b,c,d in [
                ('baseline','about 130','percent of ARA','Georgia debt exposure, baseline loss, premium, risk aversion, exact conversion'),
                ('spread','about -8 at pi=.10','points of ARA relative to baseline','baseline cost intercept, loss and equation/domain selection'),
                ('dollarization','about +18 at pi=.10','points of ARA per paper narrative','objective/FOC mapping, baseline intercepts, joint aggregation'),
                ('FXI working liquidity','up to 10','percent of ARA','Georgia QIPF specification, innovations, paired paths, drawdown statistic and overlap'),
                ('combined','145 to 150','percent of ARA','common normalization, joint channel implementation and overlap correction')]])


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--from-raw', action='store_true')
    args = parser.parse_args()
    with TemporaryDirectory() as directory:
        temp = Path(directory)
        if args.from_raw:
            sources = {}
            for name in ('source_manifest.json','r2_source_manifest.json'):
                sources.update({r['id']:r for r in load_json(ROOT/'data'/name)})
            extract_public(temp, sources)
        work = Research(temp, args.from_raw)
        work.adequacy()
        work.debt_crosscheck()
        work.liquidity()
        work.model_audit()
        outputs = {p.name:digest(p) for p in sorted((temp/REPORT).glob('*.csv'))}
        (temp/REPORT/'validation.json').write_text(json.dumps(dict(parent='ea01402129e86dde7260fbfb5524db3e5ad5888d',
            input_sha256=work.inputs, csv_sha256=outputs, checks=work.checks, status='passed',
            official_ratio_reproduced=False, optimal_target_reproduced=False), indent=2)+'\n')
        for path in sorted(p for p in temp.rglob('*') if p.is_file()):
            target = ROOT / path.relative_to(temp)
            if args.check:
                if path.read_bytes() != target.read_bytes():
                    raise ValueError('Reproduction mismatch '+str(target))
            else:
                target.parent.mkdir(parents=True,exist_ok=True)
                staged = target.with_suffix(target.suffix+'.partial')
                staged.write_bytes(path.read_bytes())
                staged.replace(target)
        print(f'{len(outputs)} analytical tables, {len(work.checks)} checks')


if __name__ == '__main__':
    main()
